package oracle

import (
	"strings"
	"testing"

	"github.com/belluikit/alidade/internal/build"
	"github.com/belluikit/alidade/internal/graph"
)

// goasmFixture is a module whose directive pins goasm v1.0.0 over a
// template file of three templates; the committed generated file lacks
// the third, as a file not regenerated after a template was added.
var goasmFixture = map[string]string{
	"go.mod": "module example.com/ga\n\ngo 1.26\n",
	"jit/goasm.go": `package jit

//go:generate go run github.com/trendvidia/goasm/cmd/goasm@v1.0.0 -arch amd64 -in templates/amd64.goasm -out emit.go

// Emitter is what the generated methods hang off.
type Emitter struct{}
`,
	"jit/templates/amd64.goasm": `# ALIAS SP = R12

# TEMPLATE PushInt(reg int)
    MOV  [SP], reg
    ADD  SP, 8

# TEMPLATE PopInt(reg int)
    SUB  SP, 8
    MOV  reg, [SP]

# TEMPLATE Later(reg int)
    MOV  [SP], reg
`,
	"jit/emit.go": `// Code generated by goasm. DO NOT EDIT.

package jit

func (e *Emitter) EmitPushInt(reg int) {}

func (e *Emitter) EmitPopInt(reg int) {}
`,
}

// TestGoasmAgrees: the generator names the methods the layer links, a
// template whose method the committed file lacks is reported, and a
// dropped and a bogus oracle edge are each caught.
func TestGoasmAgrees(t *testing.T) {
	dir := write(t, goasmFixture)
	if _, err := generator("github.com/trendvidia/goasm/cmd/goasm@v1.0.0"); err != nil {
		t.Skipf("the pinned generator is not installable here: %v", err)
	}
	g, _, err := build.Build(dir, build.DefaultOptions())
	if err != nil {
		t.Fatal(err)
	}
	o, err := GoasmTemplates(graph.NewMinter(dir), dir)
	if err != nil {
		t.Fatal(err)
	}
	if o.Templates != 3 || len(o.Failed) != 0 || len(o.NotCommitted) != 1 || !strings.Contains(o.NotCommitted[0], "#Later -> Emitter.EmitLater") {
		t.Fatalf("templates %d, failed %v, not committed %v", o.Templates, o.Failed, o.NotCommitted)
	}
	r := CompareGoasm(g, o)
	// Later's edge is the oracle's and not the graph's: the Go layer has
	// no EmitLater, so the layer's edge dropped.
	if r.Generates != [2]int{3, 2} || len(r.Extra) != 0 {
		t.Fatalf("not as expected:\n%s", r)
	}
	// PushInt's edge dropped from the oracle, and a bogus one added.
	var kept [][2]graph.ID
	for _, e := range o.Generates {
		if e[0] != "goasm://jit/templates/amd64.goasm#PushInt" {
			kept = append(kept, e)
		}
	}
	o.Generates = append(kept, [2]graph.ID{"goasm://jit/templates/amd64.goasm#PushInt", "go://example.com/ga/jit#Emitter.EmitNothing"})
	if r := CompareGoasm(g, o); len(r.Missing) != 2 || len(r.Extra) != 1 {
		t.Errorf("missing %v, extra %v; want Later's and the bogus one, and PushInt's", r.Missing, r.Extra)
	}
}
